  ('Physics', 'AQA', 'gcse', '4.1', 'Energy', 'What are renewable energy resources?', 'Resources that will be replenished, e.g. solar, wind, hydroelectric, tidal, geothermal, biofuel and wave.', 16),
  ('Physics', 'AQA', 'gcse', '4.1', 'Energy', 'Give an advantage and disadvantage of fossil fuels.', 'Advantage: reliable and can meet demand. Disadvantage: produce CO₂ and will run out.', 17),
