  ('Physics', 'AQA', 'gcse', '4.1', 'Energy', 'Give an advantage and disadvantage of solar power.', 'Advantage: renewable, no emissions. Disadvantage: no power at night and less in cloudy weather.', 19),
  ('Physics', 'AQA', 'gcse', '4.1', 'Energy', 'Give an advantage and disadvantage of nuclear power.', 'Advantage: no CO₂ and reliable. Disadvantage: radioactive waste and risk of accidents.', 20),
  ('Physics', 'AQA', 'gcse', '4.1', 'Energy', 'What is work done?', 'Energy transferred when a force moves an object: W = F × d.', 21),
