  ('Physics', 'AQA', 'gcse', '4.1', 'Energy', 'Calculate the work done when a 20 N force moves an object 5 m.', '20 × 5 = 100 J.', 23),
  ('Physics', 'AQA', 'gcse', '4.1', 'Energy', 'What is power?', 'The rate of doing work (energy transferred per second): P = E/t.', 24),
  ('Physics', 'AQA', 'gcse', '4.1', 'Energy', 'Calculate the power of a motor that transfers 600 J in 20 s.', '600 ÷ 20 = 30 W.', 25),
  ('Physics', 'AQA', 'gcse', '4.1', 'Energy', 'What is 1 watt?', '1 joule of energy transferred per second.', 26),
  ('Physics', 'AQA', 'gcse', '4.1', 'Energy', 'Why is work done against friction wasted?', 'It transfers energy to thermal stores, heating the surroundings.', 27),
  ('Physics', 'AQA', 'gcse', '4.1', 'Energy', 'What happens to energy when you push a box along the floor?', 'Work is done against friction, transferring energy to thermal energy.', 28),
  ('Physics', 'AQA', 'gcse', '4.1', 'Energy', 'What happens to energy when a car brakes?', 'Kinetic energy is transferred to thermal energy in the brakes.', 29),
  ('Physics', 'AQA', 'gcse', '4.1', 'Energy', 'How is work done related to energy transfer?', 'Work done equals energy transferred.', 30),
  ('Physics', 'AQA', 'gcse', '4.2', 'Electricity', 'What is electric current?', 'The rate of flow of charge: I = Q/t.', 1),
  ('Physics', 'AQA', 'gcse', '4.2', 'Electricity', 'What is potential difference?', 'The energy transferred per unit charge between two points: V = E/Q.', 2),
  ('Physics', 'AQA', 'gcse', '4.2', 'Electricity', 'What is resistance?', 'How much a component opposes the flow of current: R = V/I.', 3),
  ('Physics', 'AQA', 'gcse', '4.2', 'Electricity', 'What is Ohm''s law?', 'The current through a resistor is directly proportional to the potential difference, at constant temperature.', 4),
  ('Physics', 'AQA', 'gcse', '4.2', 'Electricity', 'Calculate the current when 12 V is applied across a 4 Ω resistor.', 'I = 12 ÷ 4 = 3 A.', 5),
  ('Physics', 'AQA', 'gcse', '4.2', 'Electricity', 'Calculate the charge that flows when 2 A flows for 30 s.', 'Q = 2 × 30 = 60 C.', 6),
  ('Physics', 'AQA', 'gcse', '4.2', 'Electricity', 'What is a series circuit?', 'A circuit where components are connected in a single loop.', 7),
  ('Physics', 'AQA', 'gcse', '4.2', 'Electricity', 'What is a parallel circuit?', 'A circuit where components are connected on separate branches.', 8),
  ('Physics', 'AQA', 'gcse', '4.2', 'Electricity', 'What happens to current in a series circuit?', 'It is the same everywhere.', 9),
  ('Physics', 'AQA', 'gcse', '4.2', 'Electricity', 'What happens to potential difference in a series circuit?', 'It is shared between the components.', 10),
  ('Physics', 'AQA', 'gcse', '4.2', 'Electricity', 'What happens to current in a parallel circuit?', 'It is shared between the branches; the total current equals the sum of the branch currents.', 11),
  ('Physics', 'AQA', 'gcse', '4.2', 'Electricity', 'What happens to potential difference in a parallel circuit?', 'It is the same across each branch.', 12),
