  ('Physics', 'AQA', 'gcse', '4.5', 'Forces', 'Calculate the force needed to stretch a spring with k = 50 N/m by 0.2 m.', '50 × 0.2 = 10 N.', 30),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What is a wave?', 'A disturbance that transfers energy from one place to another without transferring matter.', 1),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What is a transverse wave?', 'A wave where the vibrations are at right angles to the direction of energy transfer, e.g. light.', 2),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What is a longitudinal wave?', 'A wave where the vibrations are parallel to the direction of energy transfer, e.g. sound.', 3),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What is amplitude?', 'The maximum displacement of a point on the wave from its rest position.', 4),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What is wavelength?', 'The distance from one point on a wave to the same point on the next wave.', 5),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What is frequency?', 'The number of waves passing a point each second, measured in hertz (Hz).', 6),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What is the period of a wave?', 'The time for one complete wave to pass a point: T = 1/f.', 7),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What is the wave equation?', 'Wave speed = frequency × wavelength (v = fλ).', 8),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'A wave has frequency 50 Hz and wavelength 2 m. What is its speed?', '50 × 2 = 100 m/s.', 9),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What is the equation linking speed, distance and time for waves?', 'v = x/t.', 10),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What are compressions and rarefactions?', 'Regions in a longitudinal wave where particles are close together (compressions) and spread apart (rarefactions).', 11),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What is reflection?', 'When a wave bounces off a surface.', 12),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What is refraction?', 'The change in direction of a wave as it passes from one medium to another, due to a change in speed.', 13),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'Why do waves refract?', 'They change speed when entering a different medium.', 14),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What happens to light entering glass from air?', 'It slows down and bends towards the normal.', 15),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What is the normal?', 'An imaginary line at 90° to the surface where the wave hits.', 16),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'How can the speed of sound in air be measured?', 'Measure the time for sound to travel a known distance, e.g. using an echo or two microphones, then use v = d/t.', 17),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'How can the speed of water waves be measured in a ripple tank?', 'Measure the wavelength using a strobe or ruler and count the frequency, then use v = fλ.', 18),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What is the electromagnetic spectrum?', 'A continuous range of transverse waves that travel at the speed of light in a vacuum.', 19),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'List the EM spectrum in order of increasing frequency.', 'Radio, microwaves, infrared, visible light, ultraviolet, X-rays, gamma rays.', 20),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What is the speed of EM waves in a vacuum?', '3 × 10⁸ m/s.', 21),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What are the uses of radio waves?', 'Broadcasting TV and radio, and communications.', 22),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What are the uses of microwaves?', 'Cooking, satellite communications and mobile phones.', 23),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What are the uses of infrared?', 'Heating, thermal imaging, remote controls and optical fibres.', 24),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What are the uses of visible light?', 'Seeing, photography and fibre optic communication.', 25),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What are the uses of ultraviolet?', 'Fluorescent lamps, security marking, sterilising water and sun tanning.', 26),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What are the uses of X-rays?', 'Medical imaging and airport security scanners.', 27),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What are the uses of gamma rays?', 'Sterilising medical equipment, treating cancer and medical tracers.', 28),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What are the dangers of ultraviolet?', 'Skin damage, premature ageing, sunburn, skin cancer and eye damage.', 29),
  ('Physics', 'AQA', 'gcse', '4.6', 'Waves', 'What are the dangers of X-rays and gamma rays?', 'They are ionising radiation and can cause mutations and cancer.', 30),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'What is a magnetic field?', 'A region where a magnetic material or magnet experiences a force.', 1),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'What is the direction of a magnetic field line?', 'From the north pole to the south pole.', 2),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'What happens when like magnetic poles are brought together?', 'They repel.', 3),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'What happens when unlike magnetic poles are brought together?', 'They attract.', 4),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'What is a permanent magnet?', 'A magnet that produces its own magnetic field all the time.', 5),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'What is an induced magnet?', 'A material that becomes magnetic when placed in a magnetic field, and loses it when removed.', 6),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'Name three magnetic materials.', 'Iron, nickel and cobalt (and steel).', 7),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'How can you plot a magnetic field?', 'Using a plotting compass placed around the magnet and marking the direction of the needle.', 8),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'What is the Earth''s magnetic field evidence?', 'A compass points north because the Earth has a magnetic field; its core is magnetic.', 9),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'What is the magnetic field around a current-carrying wire?', 'Concentric circles around the wire.', 10),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'How can you find the direction of the field around a wire?', 'Using the right-hand grip rule: thumb points in the current direction and fingers curl in the field direction.', 11),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'What is a solenoid?', 'A coil of wire that produces a magnetic field when current flows through it, similar to a bar magnet.', 12),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'How can the strength of a solenoid be increased?', 'More turns, a larger current, and adding an iron core.', 13),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'What is an electromagnet?', 'A solenoid with an iron core, which can be switched on and off.', 14),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'Give two uses of electromagnets.', 'Scrap yard cranes, electric bells, relays and door locks.', 15),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'What is the motor effect?', 'A current-carrying wire in a magnetic field experiences a force.', 16),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'What is Fleming''s left-hand rule?', 'First finger = field, second finger = current, thumb = motion (force).', 17),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'What is the equation for the force on a wire in a magnetic field?', 'F = B × I × l.', 18),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'What is magnetic flux density?', 'A measure of the strength of a magnetic field, measured in tesla (T).', 19),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'Calculate the force on a 0.5 m wire carrying 2 A in a 0.1 T field.', 'F = 0.1 × 2 × 0.5 = 0.1 N.', 20),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'What is electromagnetic induction?', 'Generating a potential difference in a conductor when it moves relative to a magnetic field.', 21),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'How can the induced potential difference be increased?', 'Moving the magnet or wire faster, using a stronger magnet, or using more turns on the coil.', 22),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'When is a current induced?', 'When the conductor is part of a complete circuit.', 23),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'What is the generator effect?', 'Producing electricity by electromagnetic induction.', 24),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'How does an alternator work?', 'A coil rotates in a magnetic field, inducing an alternating current, with slip rings and brushes.', 25),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'How does a dynamo work?', 'A coil rotates in a magnetic field, inducing a direct current, using a split-ring commutator.', 26),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'How does a microphone work?', 'Sound waves make a diaphragm and coil vibrate in a magnetic field, inducing a current that matches the sound.', 27),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'What is a transformer?', 'A device that changes the size of an alternating voltage.', 28),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'How does a transformer work?', 'AC in the primary coil creates a changing magnetic field in the iron core, inducing an AC voltage in the secondary coil.', 29),
  ('Physics', 'AQA', 'gcse', '4.7', 'Magnetism and Electromagnetism', 'Why do transformers only work with AC?', 'A changing magnetic field is needed to induce a voltage; DC produces a constant field.', 30),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What is the solar system?', 'The Sun and everything that orbits it: planets, dwarf planets, moons, asteroids and comets.', 1),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What are the eight planets in order from the Sun?', 'Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune.', 2),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What keeps planets in orbit?', 'The gravitational force of the Sun.', 3),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What is a moon?', 'A natural satellite that orbits a planet.', 4),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What is an artificial satellite?', 'A man-made object placed in orbit around the Earth, e.g. for communication or weather monitoring.', 5),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'How does orbital speed change with distance?', 'Objects closer to the body they orbit must travel faster to stay in orbit.', 6),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What was the geocentric model?', 'The early model with the Earth at the centre of the universe.', 7),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What is the heliocentric model?', 'The model with the Sun at the centre of the solar system.', 8),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What evidence supported the heliocentric model?', 'Galileo''s observations of Jupiter''s moons orbiting Jupiter and the phases of Venus.', 9),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'How is a star formed?', 'A cloud of gas and dust (nebula) collapses under gravity, heats up, and nuclear fusion begins.', 10),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What is the life cycle of a star like the Sun?', 'Nebula → protostar → main sequence star → red giant → white dwarf.', 11),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What is the life cycle of a massive star?', 'Nebula → protostar → main sequence → red supergiant → supernova → neutron star or black hole.', 12),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What keeps a main sequence star stable?', 'The outward pressure from fusion balances the inward force of gravity.', 13),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What is a supernova?', 'The explosion of a massive star at the end of its life.', 14),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What is a black hole?', 'A region where gravity is so strong that not even light can escape.', 15),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What is red-shift?', 'The increase in wavelength of light from galaxies moving away from us.', 16),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What does red-shift tell us about the universe?', 'Distant galaxies are moving away from us, and more distant galaxies are moving away faster, so the universe is expanding.', 17),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What is the Big Bang theory?', 'The theory that the universe began from a very small, hot, dense region and has been expanding ever since.', 18),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What is the Steady State theory?', 'The theory that the universe has always existed and new matter is created as it expands.', 19),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What is the cosmic microwave background (CMB)?', 'Radiation left over from the early universe, detected in all directions.', 20),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'Why does the CMB support the Big Bang theory?', 'It is predicted by the Big Bang and can''t be explained by the Steady State theory.', 21),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'How do we observe the universe?', 'Using telescopes that detect different parts of the EM spectrum.', 22),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'Why are some telescopes placed in space?', 'To avoid absorption and distortion of radiation by the Earth''s atmosphere.', 23),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What is a galaxy?', 'A large group of billions of stars held together by gravity.', 24),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What galaxy is our solar system in?', 'The Milky Way.', 25),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What is a light year?', 'The distance light travels in one year.', 26),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What is nuclear fusion in stars?', 'Hydrogen nuclei join to form helium, releasing large amounts of energy.', 27),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'Where are heavy elements made?', 'In supernovae (elements heavier than iron) and in massive stars.', 28),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What is a dwarf planet?', 'A body that orbits the Sun and is nearly round, but hasn''t cleared its orbit of other objects, e.g. Pluto.', 29),
  ('Physics', 'AQA', 'gcse', '4.8', 'Space Physics', 'What is a comet?', 'A ball of ice and dust in a highly elliptical orbit around the Sun.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Physics' AND exam_board = 'AQA' AND level = 'gcse'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;
